//! The analytic validation suite (#16): the published table matches the code, every check passes,
//! and each check fails when the method is not accurate enough, so the comparisons have teeth.

use mjk_dynamics::IntegratorKind;
use mjk_sim::validation::analytic::{
    AnalyticError, Check, Measure, analytic_study, axisymmetric_precession, complete_elliptic_k,
    fitted_order, free_fall, intermediate_axis, markdown, nominal_order, passed,
    projectile_with_drag, tolerance_from,
};

/// The table the book includes, generated by `mjk validate analytic`.
const PUBLISHED: &str = include_str!("../../../docs/src/validation/analytic.md");

#[test]
fn the_published_table_matches_the_code() {
    let checks = analytic_study().expect("the test bodies are physical");
    assert_eq!(
        markdown(&checks),
        PUBLISHED,
        "regenerate with: cargo run -p mjk-cli -- validate analytic > docs/src/validation/analytic.md"
    );
}

#[test]
fn every_check_passes_and_states_why() {
    let checks = analytic_study().expect("the test bodies are physical");
    assert_eq!(checks.len(), 18);
    for check in &checks {
        assert!(check.passed(), "{check:?}");
        assert!(!check.why.is_empty() && check.tolerance > 0.0, "{check:?}");
    }
}

// ---------------------------------------------------------------- the checks have teeth

/// True if any check failed.
fn any_failed(checks: &[Check]) -> bool {
    checks.iter().any(|check| !check.passed())
}

#[test]
fn a_first_order_method_fails_the_physics_checks() {
    let euler = IntegratorKind::ExplicitEuler;
    assert!(any_failed(&free_fall(euler).expect("physical")));
    assert!(any_failed(&projectile_with_drag(euler).expect("physical")));
    assert!(any_failed(
        &axisymmetric_precession(euler).expect("physical")
    ));
    assert!(any_failed(&intermediate_axis(euler).expect("physical")));
    // Semi-implicit Euler conserves energy better, but is still first order.
    let semi = IntegratorKind::SemiImplicitEuler;
    assert!(any_failed(&projectile_with_drag(semi).expect("physical")));
    assert!(any_failed(
        &axisymmetric_precession(semi).expect("physical")
    ));
}

#[test]
fn rk4_passes_the_physics_checks_too() {
    // The physics checks hold for both fourth-order methods.
    let rk4 = IntegratorKind::Rk4;
    assert!(!any_failed(&free_fall(rk4).expect("physical")));
    assert!(!any_failed(&projectile_with_drag(rk4).expect("physical")));
    assert!(!any_failed(
        &axisymmetric_precession(rk4).expect("physical")
    ));
}

// ---------------------------------------------------------------- pieces

#[test]
fn the_elliptic_integral_matches_40_digit_values() {
    // K(k) from a 40-digit arithmetic–geometric mean.
    let cases = [
        (0.0, core::f64::consts::FRAC_PI_2),
        (0.5, 1.854_074_677_301_371_9),
        (0.81, 2.280_549_138_422_770_2),
        // The largest double below 1, the slowest case for the mean.
        (1.0 - f64::EPSILON / 2.0, 19.754_694_645_958_44),
    ];
    for (k_squared, expected) in cases {
        let k = complete_elliptic_k(k_squared).expect("in range");
        assert!(
            ((k - expected) / expected).abs() <= 2.0 * f64::EPSILON,
            "K({k_squared}) = {k}"
        );
    }
    for k_squared in [1.0, -0.1, f64::NAN, 2.0] {
        assert_eq!(complete_elliptic_k(k_squared), None, "{k_squared}");
    }
}

#[test]
fn a_fitted_order_recovers_a_power_law() {
    let steps = [16.0_f64, 32.0, 64.0, 128.0].map(|hz| 1.0 / hz);
    for power in [1.0, 2.0, 4.0] {
        let errors = steps.map(|h| 3.0 * libm::pow(h, power));
        assert!((fitted_order(errors) - power).abs() < 1e-12, "{power}");
    }
    let nominal = IntegratorKind::ALL.map(nominal_order);
    assert_eq!(
        nominal.map(f64::to_bits),
        [1.0_f64, 1.0, 4.0, 4.0].map(f64::to_bits)
    );
}

#[test]
fn a_tolerance_is_ten_times_the_estimate_rounded_up_to_a_power_of_ten() {
    for (estimate, tolerance) in [(1.1e-9, 1e-7), (2.2e-10, 1e-8), (5e-10, 1e-8), (1.0, 10.0)] {
        assert!(
            (tolerance_from(estimate) / tolerance - 1.0).abs() < 1e-12,
            "{estimate}"
        );
    }
}

#[test]
fn checks_measure_and_report_their_errors() {
    let relative = Check::new("r", 4.0, 4.000_002, "s").relative();
    assert_eq!(relative.measure, Measure::Relative);
    assert!((relative.error - 5e-7).abs() < 1e-15);
    let failing = Check::new("f", 1.0, 1.5, "m").with_tolerance(0.1, "because".to_owned());
    assert!(!failing.passed());
    let unknown = Check::new("n", 1.0, f64::NAN, "m").with_tolerance(1.0, "because".to_owned());
    assert!(!unknown.passed(), "a NaN never passes");
    let table = markdown(&[failing.clone(), failing]);
    assert!(
        table.contains("| 1 | f | 1.000000000 | 1.500000000 | 5.0e-1 m | 1e-1 m | Fail |"),
        "{table}"
    );
    assert!(table.contains("- **1–2.** because"), "{table}");
}

#[test]
fn errors_explain_themselves() {
    let rate = AnalyticError::from(mjk_dynamics::RateError::Zero);
    assert_eq!(
        rate.to_string(),
        "a physics rate is not usable: a rate must be at least 1 Hz"
    );
    let mass = mjk_dynamics::mass::MassProperties::new(
        -1.0,
        mjk_math::Vec3::zero(),
        mjk_math::Mat3::identity(),
    )
    .expect_err("negative mass");
    assert_eq!(
        AnalyticError::from(mass).to_string(),
        format!("a test body is not physical: {mass}")
    );
}

#[test]
fn the_study_passes_only_if_every_check_does() {
    let mut checks = analytic_study().expect("the bodies are physical");
    assert!(passed(&checks));
    let last = checks.len() - 1;
    checks[last].error = checks[last].tolerance;
    assert!(passed(&checks), "an error equal to its tolerance passes");
    checks[last].error = 2.0 * checks[last].tolerance;
    assert!(!passed(&checks));
    assert!(passed(&[]));
}
